begin;
do $test$
declare owner uuid; recipient uuid; mail text; wid uuid:=gen_random_uuid(); inv jsonb; iid uuid; denied boolean; result jsonb; fresh uuid:=gen_random_uuid(); freshmail text;
begin
 select id into strict owner from auth.users where email='markcamus06@gmail.com';
 select id,email into strict recipient,mail from auth.users where email='mecobuendia1@gmail.com';
 insert into public.opsfusion_workspaces(id,owner_id,name,state) values(wid,owner,'ROLLBACK invitation test','{"identities":[{"id":"INV-EMP","displayName":"Fixture","status":"Active"}]}');
 perform set_config('request.jwt.claim.sub',recipient::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.opsfusion_invitations_manage('create',wid,jsonb_build_object('email',mail,'kind','staff'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Nonowner invited';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',owner::text,true);execute 'set local role authenticated';
 inv:=public.opsfusion_invitations_manage('create',wid,jsonb_build_object('email',mail,'kind','staff'));iid:=(inv->>'id')::uuid;
 denied:=false;begin perform public.opsfusion_invitations_manage('resend',null,jsonb_build_object('id',iid));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Resend not throttled';end if;
 denied:=false;begin perform public.opsfusion_invitations_manage('create',wid,jsonb_build_object('email',mail,'kind','staff'));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Duplicate accepted';end if;
 denied:=false;begin perform public.opsfusion_invitations_manage('accept',null,jsonb_build_object('id',iid));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Wrong recipient accepted';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',recipient::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.opsfusion_invitations_manage('accept',null,jsonb_build_object('id',iid));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Unsent invitation accepted';end if;
 execute 'reset role';
 if exists(select 1 from public.opsfusion_memberships where workspace_id=wid) then raise exception 'Pending invitation granted access';end if;
 update public.opsfusion_invitations set delivery='sent',expires_at=now()-interval '1 second' where id=iid;
 execute 'set local role authenticated';denied:=false;begin perform public.opsfusion_invitations_manage('accept',null,jsonb_build_object('id',iid));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Expired invitation accepted';end if;
 execute 'reset role';update public.opsfusion_invitations set expires_at=now()+interval '1 hour' where id=iid;
 execute 'set local role authenticated';perform public.opsfusion_invitations_manage('accept',null,jsonb_build_object('id',iid));execute 'reset role';
 if not exists(select 1 from public.opsfusion_memberships where workspace_id=wid and user_id=recipient and role='technician') then raise exception 'Membership missing';end if;
 delete from public.opsfusion_memberships where workspace_id=wid;
 execute 'set local role authenticated';result:=public.opsfusion_invitations_manage('accept',null,jsonb_build_object('id',iid));execute 'reset role';
 if exists(select 1 from public.opsfusion_memberships where workspace_id=wid) then raise exception 'Replay restored revoked access';end if;
 perform set_config('request.jwt.claim.sub',owner::text,true);execute 'set local role authenticated';
 inv:=public.opsfusion_invitations_manage('create',wid,jsonb_build_object('email',mail,'kind','employee','identity_id','INV-EMP'));iid:=(inv->>'id')::uuid;
 execute 'reset role';update public.opsfusion_invitations set delivery='sent' where id=iid;
 perform set_config('request.jwt.claim.sub',recipient::text,true);execute 'set local role authenticated';perform public.opsfusion_invitations_manage('accept',null,jsonb_build_object('id',iid));execute 'reset role';
 if not exists(select 1 from public.opsfusion_employee_access where workspace_id=wid and user_id=recipient) then raise exception 'Portal enrollment missing';end if;
 if exists(select 1 from public.opsfusion_memberships where workspace_id=wid) then raise exception 'Employee invitation granted IT access';end if;
 perform set_config('request.jwt.claim.sub',owner::text,true);execute 'set local role authenticated';inv:=public.opsfusion_invitations_manage('create',wid,jsonb_build_object('email',mail,'kind','staff'));iid:=(inv->>'id')::uuid;perform public.opsfusion_invitations_manage('cancel',null,jsonb_build_object('id',iid));execute 'reset role';
 perform set_config('request.jwt.claim.sub',recipient::text,true);execute 'set local role authenticated';denied:=false;begin perform public.opsfusion_invitations_manage('accept',null,jsonb_build_object('id',iid));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Cancelled invitation accepted';end if;
 denied:=false;begin perform * from public.opsfusion_invitations;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Raw invitation table exposed';end if;
 execute 'reset role';
 freshmail:='invitation-fixture-'||fresh::text||'@example.invalid';
 insert into auth.users(id,email,email_confirmed_at,encrypted_password,raw_user_meta_data,raw_app_meta_data) values(fresh,freshmail,now(),'','{}','{}');
 perform set_config('request.jwt.claim.sub',owner::text,true);execute 'set local role authenticated';
 inv:=public.opsfusion_invitations_manage('create',wid,jsonb_build_object('email',freshmail,'kind','staff'));iid:=(inv->>'id')::uuid;
 execute 'reset role';update public.opsfusion_invitations set delivery='sent' where id=iid;
 perform set_config('request.jwt.claim.sub',fresh::text,true);execute 'set local role authenticated';
 result:=public.opsfusion_invitations_manage('mine');if not (result->>'needs_password')::boolean then raise exception 'New recipient not prompted for password';end if;
 denied:=false;begin perform public.opsfusion_invitations_manage('accept',null,jsonb_build_object('id',iid));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Passwordless recipient accepted';end if;
 execute 'reset role';if (select count(*) from public.opsfusion_audit_events where workspace_id=wid and action='Invitation accepted')<>2 then raise exception 'Acceptance audit missing or duplicate';end if;
end $test$;
rollback;
